{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE hox_db.maplemonk.HOX_DB_YFLHOME_PAYMENT_RECON_CONSOLIDATED AS WITH COD_orders AS ( SELECT REFERENCE_CODE, date(order_date) AS ORDER_DATE, CUSTOMER_ID, MARKETPLACE, ORDER_ID, ORDER_STATUS, PAYMENT_MODE, SUM(QUANTITY), SUM(SELLING_PRICE) AS CX_RECEIVED_AMOUNT, COUNT(REFERENCE_CODE) AS SKU_COUNT FROM hox_db.maplemonk.HOX_DB_YFLHOME_SALES_CONSOLIDATED WHERE upper(SHOP_NAME)=\'SHOPIFY_YFLHOME\' AND upper(PAYMENT_MODE)=\'COD\' AND date(order_date) between \'2024-06-01\' and \'2025-03-31\' GROUP BY 1,2,3,4,5,6,7 ), CLICKPOST_DATA AS ( SELECT *, LENGTH(\"Product SKU Code\") - LENGTH(REPLACE(\"Product SKU Code\", \',\', \'\')) + 1 AS SKU_COUNT FROM ( SELECT \"Order ID\", FINAL_STATUS, Courier_Partner, SUM(Clickpost_Amount) AS Clickpost_Amount, SUM(Delhivery_Amount) AS Delhivery_Amount, SUM(ShadowFx_Amount) AS ShadowFx_Amount, SUM(Ekart_Amount) AS Ekart_Amount, LISTAGG(\"Product SKU Code\",\',\') AS \"Product SKU Code\", FROM ( SELECT a.\"Order ID\", CASE WHEN UPPER(a.\"Clickpost Unified Status\") in (\'RTO-FAILED\',\'RTO-MARKED\',\'RTO-INTRANSIT\',\'RTO-DELIVERED\') THEN \'RTO\' WHEN UPPER(a.\"Clickpost Unified Status\") in (\'OUTFORPICKUP\',\'ORDERPLACED\') THEN \'OrderPlaced\' WHEN UPPER(a.\"Clickpost Unified Status\") in (\'FAILEDDELIVERY\',\'DESTINATIONHUBIN\') THEN \'InTransit\' ELSE a.\"Clickpost Unified Status\" END AS Final_Status, IFNULL(CAST(REPLACE(a.\"COD Value\",\',\',\'\') AS INT),0) as Clickpost_Amount, IFNULL(CAST(REPLACE(b.\"COD Amount\",\',\',\'\') AS INT),0) as Delhivery_Amount, IFNULL(CAST(REPLACE(c.\"COD Amount\",\',\',\'\') AS INT),0) ShadowFx_Amount, IFNULL(CAST(REPLACE(d.\"COD_AMOUNT\",\',\',\'\') AS INT),0) Ekart_Amount, a.\"Courier Partner\" as Courier_Partner, \"Product SKU Code\" FROM HOX_DB.MAPLEMONK.HOX_YFL_PAYMENT_RECON_CLICKPOST a LEFT JOIN HOX_DB.MAPLEMONK.HOX_YFL_PAYMENT_RECON_DELHIVERY b on a.AWB=b.\"Waybill Number\" LEFT JOIN HOX_DB.MAPLEMONK.HOX_YFL_PAYMENT_RECON_SHADOWFX c on a.AWB=c.AWB LEFT JOIN HOX_DB.MAPLEMONK.HOX_YFL_PAYMENT_RECON_EKART d on a.AWB=d.TRACKING_ID ) AS x GROUP BY 1,2,3 ) AS y ), COD_BASE AS ( SELECT co.*, abc.Clickpost_Amount, abc.Delhivery_Amount, abc.Ekart_Amount, abc.ShadowFx_Amount, abc.Courier_Partner, abc.\"Product SKU Code\", abc.Delhivery_Amount+abc.Ekart_Amount+abc.ShadowFx_Amount AS Total_Received, abc.SKU_COUNT, CASE WHEN abc.Final_Status IS NULL then co.ORDER_STATUS else abc.Final_Status end as Final_Status FROM COD_orders co LEFT JOIN CLICKPOST_DATA abc ON RIGHT(co.REFERENCE_CODE,LENGTH(co.REFERENCE_CODE)-LENGTH(\'#\'))=abc.\"Order ID\" and co.SKU_COUNT=abc.SKU_COUNT ), Final_Report_Cod as ( SELECT DATE_TRUNC(\'month\', ORDER_DATE) AS month_start, COURIER_PARTNER, SUM(CX_RECEIVED_AMOUNT) as TOTAL_CX_PAID, SUM(TOTAL_RECEIVED) AS TOTAL_AMOUNT_RECEIVED, SUM(CX_RECEIVED_AMOUNT)-SUM(TOTAL_RECEIVED) AS TOTAL_DIFFFERENCE FROM COD_BASE WHERE COURIER_PARTNER IS NOT NULL AND UPPER(FINAL_STATUS) IN (\'DELIVERED\',\'SHOPIFY_PROCESSED\') GROUP BY 1,2 ORDER BY 1 ASC ), Easyecom as ( SELECT REFERENCE_CODE, ORDER_DATE, COURIER,ORDER_STATUS, SHIPPING_STATUS FROM Hox_db.maplemonk.easyecom_yflhome_customer_orders WHERE lower(marketplace) in (\'shopify\',\'offline\') and date(order_date) between \'2024-06-01\' and \'2025-03-31\' ), Prepaid_orders AS ( SELECT a.REFERENCE_CODE, date(a.order_date) AS ORDER_DATE, a.CUSTOMER_ID, a.MARKETPLACE, a.ORDER_STATUS, a.PAYMENT_MODE, a.QUANTITY, a.SELLING_PRICE, b.shadowid, b.order_id, RIGHT(a.REFERENCE_CODE,LENGTH(a.REFERENCE_CODE)-LENGTH(\'#\')) as ORDER_NUM FROM hox_db.maplemonk.HOX_DB_YFLHOME_SALES_CONSOLIDATED a LEFT JOIN HOX_DB.MAPLEMONK.HOX_YFL_PAYMENT_RECON_DB b on a.REFERENCE_CODE=b.name WHERE upper(a.SHOP_NAME)=\'SHOPIFY_YFLHOME\' AND upper(a.PAYMENT_MODE)=\'PREPAID\' AND date(a.order_date) between \'2024-06-01\' and \'2025-03-31\' ), PhonePe as (SELECT *, RIGHT(b.\"PhonePe Attempt Reference Id\",LENGTH(b.\"PhonePe Attempt Reference Id\")-LENGTH(\'houseofx-\')) as pre_final_shadowId, LEFT(pre_final_shadowId,LENGTH(RIGHT(b.\"PhonePe Attempt Reference Id\",LENGTH(b.\"PhonePe Attempt Reference Id\")-LENGTH(\'houseofx-\')))-LENGTH(\'-1\')) as final_shadow_Id FROM HOX_DB.MAPLEMONK.HOX_YFL_PAYMENT_RECON_PHONEPE b ), Simpl as (SELECT *, LEFT(c.\"Order ID\",LENGTH(c.\"Order ID\")-LEN(\'-1\')) AS pre_final_shadowId, RIGHT(pre_final_shadowId,LENGTH(LEFT(c.\"Order ID\",LENGTH(c.\"Order ID\")-LENGTH(\'-1\')))-LENGTH(\'houseofx-\')) as final_shadow_Id FROM HOX_DB.MAPLEMONK.HOX_YFL_PAYMENT_RECON_SIMPL c ), PREPAID_BASE AS ( SELECT *, CASE WHEN (lower(SHIPPING_STATUS)=\'delivered\' OR lower(FINAL_STATUS)=\'delivered\' OR upper(FINAL_STATUS)=\'SHOPIFY_PROCESSED\') AND (SHIPPING_STATUS IS NOT NULL) THEN \'Delivered\' ELSE \'Other\' END AS Final_Shipping_Status FROM ( SELECT DISTINCT po.*, cte.Juspay_amount, cte.PhonePe_amount, cte.Simpl_amount, cte.payment_gateway as payment_gateway, e.courier, e.order_status, e.shipping_status, CASE WHEN clickpost.\"Clickpost Unified Status\" is NULL then po.ORDER_STATUS WHEN UPPER(clickpost.\"Clickpost Unified Status\") in (\'RTO-FAILED\',\'RTO-MARKED\',\'RTO-INTRANSIT\',\'RTO-DELIVERED\') THEN \'RTO\' WHEN UPPER(clickpost.\"Clickpost Unified Status\") in (\'OUTFORPICKUP\',\'ORDERPLACED\') THEN \'OrderPlaced\' WHEN UPPER(clickpost.\"Clickpost Unified Status\") in (\'FAILEDDELIVERY\',\'DESTINATIONHUBIN\') THEN \'InTransit\' ELSE clickpost.\"Clickpost Unified Status\" END AS Final_Status FROM Prepaid_orders po LEFT JOIN ( SELECT a.order_id, a.payment_gateway, IFNULL(CAST(REPLACE(a.amount,\',\',\'\') AS INT),0) as Juspay_amount, IFNULL(CAST(REPLACE(b.\"Total Transaction Amount\",\',\',\'\') AS INT),0) as PhonePe_amount, IFNULL(CAST(REPLACE(c.\"Net Amount (Rs.)\",\',\',\'\') AS INT),0) as Simpl_amount FROM HOX_DB.MAPLEMONK.HOX_YFL_PAYMENT_RECON_JUSPAY a LEFT JOIN PhonePe b on a.order_id=b.final_shadow_Id LEFT JOIN Simpl c on a.order_id=c.final_shadow_Id ) as cte on po.shadowId=cte.order_id LEFT JOIN HOX_DB.MAPLEMONK.HOX_YFL_PAYMENT_RECON_CLICKPOST clickpost on po.ORDER_NUM =clickpost.\"Order ID\" LEFT JOIN Hox_db.maplemonk.easyecom_yflhome_customer_orders e on po.ORDER_NUM=e.reference_code ) ), Prepaid_Base_with_rank as ( SELECT distinct * FROM ( SELECT distinct REFERENCE_CODE, ORDER_DATE, CUSTOMER_ID, MARKETPLACE, PAYMENT_MODE, QUANTITY, SELLING_PRICE, SHADOWID, ORDER_ID, ORDER_NUM, JUSPAY_AMOUNT, PHONEPE_AMOUNT, payment_gateway, SIMPL_AMOUNT, FINAL_SHIPPING_STATUS FROM PREPAID_BASE WHERE lower(Final_Shipping_Status)=\'delivered\' ) as x ), PREPAID_FINAL AS ( SELECT *, PHONEPE_AMOUNT+SIMPL_AMOUNT AS TOTAL_RECEIVED FROM ( SELECT DISTINCT a.ORDER_ID, a.ORDER_DATE, CAST(REPLACE(b.TOTAL_SALES,\',\',\'\') AS INT) AS AMOUNT, a.PAYMENT_GATEWAY, IFNULL(a.JUSPAY_AMOUNT,0) AS JUSPAY_AMOUNT, IFNULL(a.PHONEPE_AMOUNT,0) AS PHONEPE_AMOUNT, IFNULL(a.SIMPL_AMOUNT,0) AS SIMPL_AMOUNT FROM PREPAID_BASE_with_rank a LEFT JOIN ( SELECT ORDER_ID, SUM(SELLING_PRICE) AS TOTAL_SALES FROM PREPAID_BASE_with_rank GROUP BY 1 ) b ON a.ORDER_ID=b.ORDER_ID ) as a ), Final_Report_Prepaid as ( SELECT *, CX_PAID-TOTAL_RECEIVED AS DIFFERENCE FROM ( SELECT DATE_TRUNC(\'month\', ORDER_DATE) AS month_start, PAYMENT_GATEWAY, SUM(AMOUNT) AS CX_PAID, SUM(TOTAL_RECEIVED) AS TOTAL_RECEIVED FROM PREPAID_FINAL WHERE PAYMENT_GATEWAY IS NOT NULL GROUP BY 1,2 ORDER BY 1 ASC ) AS x ) SELECT * FROM Final_Report_Prepaid UNION SELECT * FROM Final_Report_COD;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from HOX_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            